import os, sys
input = lambda : sys.stdin.buffer.readline().rstrip(b'\r\n')

def dbp(*args, **kwargs):
	print(*args, file=sys.stderr, **kwargs)
a_str = lambda : input().decode('ascii')
get_int_list = lambda : [int(x) for x in input().split()]
join_str = lambda l, ch=' ': ch.join((str(x) for x in l))

def sup(a, b):
	count = 0
	for i in range(5):
		if a[i] < b[i]:
			count += 1
		if count >= 3:
			return True
	return False

def do_thing():
	n = int(input())
	g = [get_int_list() for i in range(n)]
	cand = 0
	for i in range(1, n):
		if sup(g[i], g[cand]):
			cand = i
	if all((sup(g[cand], g[i]) for i in range(n) if i != cand)):
		return cand + 1
	return -1

def multicase():
	maxcc = int(input().strip())
	for cc in range(maxcc):
		print(do_thing())
